<template>
  <section class="agent-modeling">
    <header><div><span class="eyebrow">事前定义 / Agent 建模输入</span><h2>Agent</h2><p>定义状态、决策变量、行为规则、硬约束和交互协议，再为具体主体绑定参数。</p></div><div><el-button @click="check" :loading="loading">检查输入绑定</el-button><el-button @click="exportContract">导出建模输入</el-button></div></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <div class="role-grid"><button v-for="profile in definitions" :key="profile.id" :class="{active:profile.id === activeId}" @click="choose(profile)"><strong>{{ profile.label }}</strong><span>{{ profile.states.length }} 状态 · {{ profile.decision_variables.length }} 决策 · {{ profile.behavior_rules.length }} 规则</span><small>{{ bindingCount(profile.id) }} 个主体已关联定义</small></button></div>
    <el-empty v-if="!definitions.length" description="当前保存版本尚未定义 Agent 行为，请生成或补充框架定义。" />
    <template v-if="active">
      <div class="profile-head"><div><h3>{{ active.label }} <code>{{ active.actor_type }}</code></h3><p>{{ active.goal }}</p></div><el-button type="primary" plain @click="editProfile">编辑建模定义</el-button></div>
      <div class="definition-grid">
        <article><h4>01 状态变量</h4><p>每个主体随时间更新的状态；未给定值保持待绑定。</p><div v-for="state in active.states" :key="state.id" class="state-row"><strong>{{ state.label }}</strong><span>{{ state.unit }}</span><small>绑定字段：{{ state.source_input || state.id }} · {{ state.required ? '必需' : '可选' }}</small></div></article>
        <article><h4>02 决策变量</h4><p>Agent 可以调整的动作量，不等同于观测指标。</p><div v-for="decision in active.decision_variables" :key="decision.id" class="state-row"><strong>{{ decision.label }}</strong><span>{{ decision.unit }}</span><small>{{ decision.id }} ≥ {{ decision.min }}</small></div><h4>决策节拍与状态更新</h4><p>{{ active.state_transition }}</p></article>
        <article class="wide behavior-panel"><h4>03 行为规则 · 触发 → 方法 → 决策定义 <small>共 {{ active.behavior_rules.length }} 条</small></h4><div v-for="rule in visibleBehaviorRules" :key="rule.id" class="rule-row"><el-tag effect="plain">{{ rule.trigger }}</el-tag><strong>{{ rule.method }}</strong><p>{{ rule.definition }}</p></div><el-button v-if="active.behavior_rules.length > 3" class="behavior-toggle" text type="primary" :aria-expanded="behaviorsExpanded" @click="behaviorsExpanded=!behaviorsExpanded">{{ behaviorsExpanded ? '收起规则' : `展开其余 ${active.behavior_rules.length-3} 条规则` }}</el-button><small class="behavior-note">上述为声明式建模规则，供后续建模使用；不在此处执行策略。</small></article>
        <article class="constraint-panel"><h4>04 约束边界 <small>{{ active.constraints.length }} 项定义 · {{ constraintsByCategory.length }} 类边界</small></h4><p>区分资源、时间、合同、质量和外部环境限制；缺少阈值或资质输入时保留待绑定，不默认满足。</p><section v-for="section in constraintsByCategory" :key="section.category" class="constraint-section"><h5>{{ section.category }}</h5><div v-for="item in section.items" :key="item.label+item.condition" class="constraint-card"><strong>{{ item.label }}</strong><p>{{ item.condition }}</p><small><b>不满足时</b> {{ item.response }}</small></div></section><small>当前为事前建模约束定义，尚未执行约束求解或业务合规判定。</small></article>
        <article><h4>05 交互与消息契约</h4><div v-for="interaction in active.interactions" :key="interaction.relation_id" class="protocol"><strong>{{ relationLabel(interaction.relation_id) }}</strong><p>接收：{{ interaction.receive.join('、') }}<br>发送：{{ interaction.send.join('、') }}</p><small>消息必需：{{ interaction.required_fields.join('、') }}</small></div></article>
      </div>
      <article class="environment-inputs"><h3>环境输入与约束</h3><p v-for="field in contract?.environment_model?.agent_inputs.filter(x=>x.actor_types.includes(active.actor_type)) || []" :key="field.parameter_id">{{ field.label }}：{{ field.value ?? '待补全' }} {{ field.unit }} · {{ field.effect }}</p></article><section class="binding-panel"><h3>主体参数绑定状态</h3><p v-if="!roleBindings.length">尚未为此角色绑定业务主体。框架有定义，不代表已有实际库存、产能或订单数据。</p><div v-for="binding in roleBindings" :key="`${binding.row}:${binding.entity_id}`" class="binding-row" :class="{focused:binding.entity_id===focusEntity}"><strong>{{ binding.name }}</strong><el-tag :type="binding.status==='inputs_bound'?'success':'warning'">{{ binding.status==='inputs_bound'?'状态输入已绑定':'状态输入待补全' }}</el-tag><div class="state-values"><span v-for="state in binding.states" :key="state.id">{{ state.label }}：{{ state.status==='bound' ? `${state.value} ${state.unit}` : state.reason }}</span></div><small v-if="binding.issues.length">{{ binding.issues.join('；') }}</small></div></section>
    </template>
    <p class="scope-note">{{ contract?.note || '仅定义事前建模输入；不接入事中 Agent，不会自动启动仿真。' }}</p>
    <el-dialog v-model="editing" title="编辑 Agent 建模定义" width="min(880px,95vw)">
      <div v-if="draft" class="editor"><el-form label-position="top"><div class="edit-two"><el-form-item label="角色名称"><el-input v-model="draft.label"/></el-form-item><el-form-item label="时间步长（天；清空表示待绑定）"><el-input-number :model-value="draft.step_days" :min="0.01" :max="365" @update:model-value="draft.step_days=$event ?? null"/></el-form-item></div><el-form-item label="目标"><el-input v-model="draft.goal"/></el-form-item><el-form-item label="建模粒度"><el-input v-model="draft.grain"/></el-form-item>
        <h4>状态变量</h4><div v-for="(state,index) in draft.states" :key="index" class="edit-row"><el-input v-model="state.id" placeholder="编码"/><el-input v-model="state.label" placeholder="名称"/><el-select v-model="state.source_input" clearable placeholder="输入字段或自定义"><el-option v-for="input in model.inputs" :key="input.id" :value="input.id" :label="input.label"/></el-select><el-input v-model="state.unit" placeholder="单位"/><el-switch v-model="state.required"/><el-button text type="danger" @click="draft.states.splice(index,1)">删除</el-button></div><el-button text @click="draft.states.push({id:'',label:'',unit:'件',source_input:'',required:true})">＋状态变量</el-button>
        <h4>决策变量</h4><div v-for="(decision,index) in draft.decision_variables" :key="index" class="edit-row"><el-input v-model="decision.id" placeholder="编码"/><el-input v-model="decision.label" placeholder="名称"/><el-input v-model="decision.unit" placeholder="单位"/><el-input-number v-model="decision.min" :min="0"/><el-button text type="danger" @click="draft.decision_variables.splice(index,1)">删除</el-button></div><el-button text @click="draft.decision_variables.push({id:'',label:'',unit:'件',min:0})">＋决策变量</el-button>
        <h4>行为规则</h4><div v-for="(rule,index) in draft.behavior_rules" :key="index" class="edit-block"><div class="edit-two"><el-input v-model="rule.id" placeholder="规则编码"/><el-input v-model="rule.trigger" placeholder="触发条件"/></div><el-input v-model="rule.method" placeholder="方法名称"/><el-input v-model="rule.definition" type="textarea" :rows="2" placeholder="规则 / 公式定义"/><el-button text type="danger" @click="draft.behavior_rules.splice(index,1)">删除规则</el-button></div><el-button text @click="draft.behavior_rules.push({id:'',trigger:'',method:'',definition:''})">＋行为规则</el-button>
        <h4>约束</h4><p>格式：分类｜约束名称｜约束条件｜不满足时的处理；也支持普通文本。</p><div v-for="(_,index) in draft.constraints" :key="index" class="edit-two"><el-input v-model="draft.constraints[index]" type="textarea" autosize placeholder="分类｜约束名称｜约束条件｜不满足时的处理"/><el-button text type="danger" @click="draft.constraints.splice(index,1)">删除</el-button></div><el-button text @click="draft.constraints.push('')">＋约束</el-button>
        <h4>交互协议</h4><div v-for="(port,index) in draft.interactions" :key="index" class="edit-block"><el-select v-model="port.relation_id" placeholder="本体关系"><el-option v-for="rel in model.relations" :key="rel.id" :label="rel.label" :value="rel.id"/></el-select><el-input :model-value="port.receive.join('、')" @update:model-value="port.receive=split($event)" placeholder="接收消息，顿号分隔"/><el-input :model-value="port.send.join('、')" @update:model-value="port.send=split($event)" placeholder="发送消息，顿号分隔"/><el-input :model-value="port.required_fields.join('、')" @update:model-value="port.required_fields=split($event)" placeholder="消息必需字段"/><el-button text type="danger" @click="draft.interactions.splice(index,1)">删除协议</el-button></div><el-button text @click="draft.interactions.push({relation_id:'',receive:[],send:[],required_fields:[]})">＋交互协议</el-button>
        <el-form-item label="状态更新过程"><el-input v-model="draft.state_transition" type="textarea"/></el-form-item></el-form><el-alert v-if="editError" :title="editError" type="error" :closable="false"/></div>
      <template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" @click="commit" :loading="committing">应用到框架草稿</el-button></template>
    </el-dialog>
  </section>
</template>

<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { constraintSections } from '@/utils/domainAgentConstraints'
import { previewAgentContract, validateAgentDefinitions, buildAgentDefinitions } from '@/utils/domainAgentModel'
const props=defineProps({model:{type:Object,required:true},instance:{type:Object,default:null},focusType:{type:String,default:''},focusEntity:{type:String,default:''}})
const emit=defineEmits(['update-definitions','contract','select'])
const behaviorsExpanded=ref(false)
const activeId=ref('manufacturer_agent'),contract=ref(null),loading=ref(false),error=ref(''),editing=ref(false),draft=ref(null),committing=ref(false),editError=ref('')
const definitions=computed(()=>buildAgentDefinitions(props.model))
const active=computed(()=>definitions.value.find(x=>x.id===activeId.value)||definitions.value[0])
const visibleBehaviorRules=computed(()=>behaviorsExpanded.value?active.value?.behavior_rules||[]:(active.value?.behavior_rules||[]).slice(0,3))
watch(()=>active.value?.id,()=>{behaviorsExpanded.value=false})
const constraintsByCategory=computed(()=>constraintSections(active.value))
const roleBindings=computed(()=>contract.value?.bindings.filter(x=>x.definition_id===active.value?.id)||[])
const bindingCount=id=>contract.value?.bindings.filter(x=>x.definition_id===id).length||0
const relationLabel=id=>props.model.relations.find(x=>x.id===id)?.label||id
const split=value=>value.split(/[、,\n]/).map(x=>x.trim()).filter(Boolean)
function choose(profile){activeId.value=profile.id;emit('select','types',profile.actor_type)}
watch(()=>props.focusType,type=>{const queue=[type],seen=new Set();while(queue.length){const current=queue.shift();if(seen.has(current))continue;seen.add(current);const profile=definitions.value.find(x=>x.actor_type===current);if(profile){activeId.value=profile.id;return}queue.push(...(props.model.types.find(x=>x.id===current)?.parents||[]))}})
let timer,revision=0
async function check(){const current=++revision;loading.value=true;error.value='';try{const value=await previewAgentContract(props.model,props.instance);if(current===revision){contract.value=value;emit('contract',value)}}catch(e){if(current===revision){error.value=e.message;contract.value=null;emit('contract',null)}}finally{if(current===revision)loading.value=false}}
watch([()=>props.model,()=>props.instance],()=>{clearTimeout(timer);contract.value=null;emit('contract',null);timer=setTimeout(check,250)},{deep:true,immediate:true})
onBeforeUnmount(()=>{clearTimeout(timer);revision++})
function editProfile(){draft.value=structuredClone(JSON.parse(JSON.stringify(active.value)));editError.value='';editing.value=true}
async function commit(){committing.value=true;editError.value='';try{const value=JSON.parse(JSON.stringify(draft.value));const candidate={...props.model,agent_definitions:definitions.value.map(x=>x.id===value.id?value:x)};const validation=validateAgentDefinitions(candidate);if(!validation.valid)throw new Error(validation.errors.join('；'));emit('update-definitions',candidate.agent_definitions);editing.value=false}catch(e){editError.value=e.message}finally{committing.value=false}}
async function exportContract(){await check();if(!contract.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(contract.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='事前Agent建模输入.json';a.click();URL.revokeObjectURL(url)}
</script>

<style scoped>
.agent-modeling{margin-top:18px;padding:24px;border:1px solid #dce5ef;border-radius:12px;background:#fff;color:#23344c}.agent-modeling header,.profile-head{display:flex;justify-content:space-between;align-items:center;gap:20px}.eyebrow{font-size:11px;color:#2563eb}.agent-modeling h2{font-size:20px;margin:8px 0}.agent-modeling p{font-size:12px;line-height:1.9;color:#64748b}.role-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin:20px 0}.role-grid button{padding:16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:9px;text-align:left;cursor:pointer;color:#334155}.role-grid .active{background:#eff6ff;border-color:#60a5fa}.role-grid span,.role-grid small{display:block;margin-top:9px;font-size:11px;color:#64748b}.profile-head{padding:16px 0}.profile-head h3{margin:0;font-size:17px}.profile-head code{font-size:11px;color:#94a3b8;margin-left:8px}.profile-head small{color:#b45309;font-size:11px}.definition-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.definition-grid article{padding:18px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px}.definition-grid h4{margin:0 0 12px;font-size:13px}.definition-grid .wide{grid-column:1/-1}.state-row{display:grid;grid-template-columns:1fr auto;gap:7px;padding:10px 0;border-bottom:1px solid #e2e8f0;font-size:12px}.state-row small{grid-column:1/-1;color:#94a3b8}.rule-row{padding:12px 0;border-bottom:1px solid #e2e8f0}.rule-row strong{margin-left:12px;font-size:12px}.definition-grid small,.scope-note{color:#94a3b8;font-size:11px;line-height:1.9}.constraint{padding-left:10px;border-left:2px solid #f59e0b}.protocol{border-bottom:1px solid #e2e8f0;padding:12px 0}.protocol strong{font-size:12px}.binding-panel{margin-top:18px}.binding-panel h3{font-size:14px}.binding-row{padding:14px;border:1px solid #e2e8f0;border-radius:8px;margin-top:8px;font-size:12px}.binding-row .el-tag{margin-left:12px}.binding-row.focused{border-color:#60a5fa;background:#eff6ff}.state-values{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0;color:#64748b}.binding-row small{color:#b45309}.editor{max-height:65vh;overflow:auto;padding-right:12px}.edit-two{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px}.edit-row{display:flex;gap:8px;margin-bottom:10px}.edit-row>*{min-width:0;flex:1}.edit-block{padding:12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;margin-bottom:10px}.edit-block>.el-input,.edit-block>.el-select{margin-bottom:8px}.scope-note{margin-bottom:0}@media(max-width:750px){.definition-grid{grid-template-columns:1fr}.agent-modeling header,.profile-head{align-items:flex-start;flex-wrap:wrap}.edit-row{flex-wrap:wrap}.edit-row>*{flex-basis:30%}}
.constraint-panel h4>small{margin-left:10px;font-weight:400}.constraint-section{margin-top:18px}.constraint-section h5{margin:0 0 10px;font-size:12px;color:#2563eb}.constraint-card{border-left:2px solid #f59e0b;background:#fff;padding:12px;margin:8px 0;border-radius:0 6px 6px 0}.constraint-card>strong{font-size:12px;color:#334155}.constraint-card>p{margin:7px 0!important;line-height:1.9}.constraint-card>small{display:block;color:#64748b!important}.constraint-card b{color:#b45309;font-weight:500;margin-right:5px}.definition-grid .constraint-panel{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:14px}.constraint-panel>h4,.constraint-panel>p,.constraint-panel>small{grid-column:1/-1;margin-bottom:0}.constraint-panel .constraint-section{margin-top:8px}@media(max-width:750px){.definition-grid .constraint-panel{grid-template-columns:1fr}}
.behavior-panel h4>small{margin-left:10px;font-weight:400;color:#94a3b8}.behavior-toggle{display:block;margin:10px 0}.behavior-note{display:block}@media(max-width:650px){.rule-row strong{display:block;margin:8px 0}}</style>
